#include <iostream>
#include <iomanip>

// Calculate factorial recursively using 64-bit unsigned integer
unsigned long long factorial(unsigned long long number) {
    if (number <= 1) {
        return 1; // Base cases: 0! = 1 and 1! = 1
    }
    return number * factorial(number - 1); // Recursion step
}

int main() {
    for (unsigned int counter = 0; counter <= 10; ++counter) {
        std::cout << std::setw(2) << counter << "! = " 
                  << factorial(counter) << "\n";
    }
    return 0;
}

#include <iostream>

// Recursive calculation of Fibonacci numbers
unsigned long long fibonacci(unsigned long long number) {
    // Base cases: fibonacci(0) = 0, fibonacci(1) = 1
    if (number <= 1) {
        return number;
    }
    // Recursion step: binary tree recursion
    return fibonacci(number - 1) + fibonacci(number - 2);
}

int main() {
    for (unsigned int counter = 0; counter <= 10; ++counter) {
        std::cout << "fibonacci( " << counter << " ) = " 
                  << fibonacci(counter) << "\n";
    }
    return 0;
}
